-- # Lernfeld 5: Cyberphysische Systeme > ## Datenbanken > - Systeme

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können relationale Datenbanksysteme auch unstrukturierte Daten effizient verwalten?', 2, '[{"text": "Nein", "correct": true, "because": "Sie sind für strukturierte Daten optimiert"}, {"text": "Ja", "correct": false, "because": "NoSQL besser für Unstrukturiertes"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein NoSQL-Datenbanksystem immer schneller als ein relationales System?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Anwendungsfall ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell überlegen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Datenbanksysteme ohne Transaktionsunterstützung Datenintegrität gewährleisten?', 2, '[{"text": "Nein", "correct": true, "because": "Transaktionen sichern Konsistenz"}, {"text": "Ja", "correct": false, "because": "Integrität leidet ohne Transaktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind alle Datenbanksysteme gleichermaßen für Big Data geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierung und Struktur variieren"}, {"text": "Ja", "correct": false, "because": "Unterschiede in Design"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Datenbanksystem ohne ACID-Eigenschaften für Finanzanwendungen sicher sein?', 2, '[{"text": "Nein", "correct": true, "because": "ACID sichert Zuverlässigkeit"}, {"text": "Ja", "correct": false, "because": "Finanzdaten brauchen Garantien"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Datenbanksystem ist ein bekanntes Beispiel für ein relationales System?', 2, '[{"text": "MySQL", "correct": true, "because": "Tabellenbasiertes RDBMS"}, {"text": "MongoDB", "correct": false, "because": "NoSQL"}, {"text": "Cassandra", "correct": false, "because": "NoSQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System eignet sich am besten für unstrukturierte Daten wie JSON?', 3, '[{"text": "MongoDB", "correct": true, "because": "Dokumentenorientiertes NoSQL"}, {"text": "PostgreSQL", "correct": false, "because": "Relational, aber flexibel"}, {"text": "SQLite", "correct": false, "because": "Relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal unterscheidet NoSQL-Systeme von relationalen Systemen?', 2, '[{"text": "Skalierbarkeit über Flexibilität", "correct": true, "because": "NoSQL skaliert horizontal"}, {"text": "Strikte Schemata", "correct": false, "because": "Relationaler Ansatz"}, {"text": "SQL-Unterstützung", "correct": false, "because": "NoSQL oft ohne SQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Datenbanksystem ist für verteilte Big-Data-Anwendungen optimiert?', 2, '[{"text": "Cassandra", "correct": true, "because": "Entwickelt für Verteilung"}, {"text": "Oracle", "correct": false, "because": "Relational, zentraler Fokus"}, {"text": "MySQL", "correct": false, "because": "Relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System bietet ACID-Garantien für Transaktionen?', 2, '[{"text": "PostgreSQL", "correct": true, "because": "Vollständige ACID-Unterstützung"}, {"text": "Redis", "correct": false, "because": "NoSQL, begrenzte Transaktionen"}, {"text": "Neo4j", "correct": false, "because": "Graph-DB, nicht vollständig ACID"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Datenbanksysteme gehören zur Kategorie der relationalen Systeme?', 4, '[{"text": "MySQL", "correct": true, "because": "Tabellenbasiert"}, {"text": "PostgreSQL", "correct": true, "because": "RDBMS mit SQL"}, {"text": "MongoDB", "correct": false, "because": "NoSQL"}, {"text": "SQLite", "correct": true, "because": "Leichtgewichtiges RDBMS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften unterscheiden NoSQL-Systeme?', 3, '[{"text": "Flexible Schemata", "correct": true, "because": "Keine festen Tabellen"}, {"text": "Horizontale Skalierung", "correct": true, "because": "Verteilte Architektur"}, {"text": "Strikte Konsistenz", "correct": false, "because": "Oft eventual consistency"}, {"text": "Dokumentenorientierung", "correct": true, "because": "Z.B. JSON-Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl eines Datenbanksystems?', 3, '[{"text": "Datenstruktur", "correct": true, "because": "Strukturiert vs. unstrukturiert"}, {"text": "Skalierungsanforderungen", "correct": true, "because": "Vertikal vs. horizontal"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Irrelevant"}, {"text": "Transaktionsvolumen", "correct": true, "because": "Leistung entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenbanksysteme sind für spezifische Anwendungsfälle optimiert?', 4, '[{"text": "Neo4j für Graphdaten", "correct": true, "because": "Beziehungsorientiert"}, {"text": "Redis für In-Memory-Caching", "correct": true, "because": "Schnelle Zugriffe"}, {"text": "MySQL für Web-Anwendungen", "correct": true, "because": "Weit verbreitet"}, {"text": "Excel für Datenbanken", "correct": false, "because": "Kein DBMS"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten relationale Datenbanksysteme?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "ACID-Eigenschaften"}, {"text": "SQL-Standard", "correct": true, "because": "Einheitliche Abfragesprache"}, {"text": "Hohe Flexibilität bei Schemata", "correct": false, "because": "NoSQL-Stärke"}, {"text": "Strukturierte Datenverwaltung", "correct": true, "because": "Tabellenbasiert"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Relationale Systeme sind für unstrukturierte Daten ideal. b) NoSQL-Systeme bieten oft horizontale Skalierung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Relationale für Struktur, NoSQL skalierbar"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MySQL unterstützt ACID-Transaktionen. b) MongoDB ist ein relationales System.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MySQL ACID, MongoDB NoSQL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) NoSQL-Systeme sind immer schemalos. b) Relationale Systeme sind für Big Data ungeeignet.', 3, '[{"text": "Beides falsch", "correct": true, "because": "NoSQL teils schematisch, RDBMS skalierbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Cassandra ist für verteilte Daten optimiert. b) SQLite ist für große Unternehmensanwendungen ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cassandra verteilt, SQLite leichtgewichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Datenbanksysteme ohne SQL sind immer NoSQL. b) ACID ist für alle Anwendungen zwingend erforderlich.', 3, '[{"text": "Beides falsch", "correct": true, "because": "SQL in manchen NoSQL, ACID nicht immer nötig"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]');

